            try (InputStream inputStream = url.openStream()) {
                BufferedImage image = ImageIO.read(inputStream);
                // ImageIO.read returns null if the stream does not contain a recognized image format
                return image != null;
            }
        } catch (Exception e) {
            // Catches MalformedURLException, IOException, and any runtime exceptions during parsing
            return false;
        }
    }
}
